INSERT INTO relationship_type (relationship_type, category, is_symmetric, description) VALUES
('AnnouncedTo', 'Spiritual', false, 'Subject (a messenger) announced a birth, event or message to the object.'),
('AppearedTo', 'Spiritual', false, 'Subject (a spiritual being) appeared to the object.'),
('MinisteredTo', 'Spiritual', false, 'Subject strengthened, fed or attended to the object.'),
('Tempted', 'Spiritual', false, 'Subject tempted or incited the object to sin.'),
('Accused', 'Spiritual', false, 'Subject accused the object before God.'),
('Afflicted', 'Spiritual', false, 'Subject afflicted the object with illness or torment.'),
('Possessed', 'Spiritual', false, 'Subject (a spirit) possessed or entered the object.'),
('CastOut', 'Spiritual', false, 'Subject cast the object (a spirit) out of the person it possessed.'),
('Worshipped', 'Spiritual', false, 'Subject worshipped, served or consulted the object (a deity).')
INSERT INTO spiritual_being (being_id, display_name, also_known_as, being_kind, being_type, name_status, testament, appears_in_both_testaments, summary, summary_source, first_reference, verse_count, source_record_id) VALUES
('satan_2476', 'Satan', 'the devil; the tempter; the accuser; the serpent; the dragon; Beelzebub; Lucifer (Isaiah 14:12, by tradition)', 'Adversary', 'SpiritualBeing', 'Named', 'Old Testament', true, 'The adversary and accuser. He provoked David to number Israel, accused and afflicted Job, stood to resist Joshua the high priest, tempted Jesus in the wilderness and entered Judas Iscariot. Revelation identifies him with the ancient serpent and the dragon cast out by Michael. Theographic''s separate ''Lucifer'' record (Isaiah 14:12, addressed to the king of Babylon) is folded in here as an alias, following the traditional identification.', 'Curated', '1 Chronicles 21:1', 56, 'satan_2476'),
('gabriel_1261', 'Gabriel', NULL, 'Angel', 'Angel', 'Named', 'Old Testament', true, 'Angel who ''stands in the presence of God''. He explained Daniel''s visions, announced the birth of John the Baptist to Zacharias and the birth of Jesus to Mary. Scripture does not call him an archangel; later tradition does.', 'Curated', 'Daniel 8:16', 4, 'gabriel_1261'),
('michael_2068', 'Michael', NULL, 'Archangel', 'Angel', 'Named', 'Old Testament', true, '''One of the chief princes'' and the great prince who stands for Daniel''s people; the only being scripture calls an archangel. He contended with the devil over the body of Moses and leads the angels who cast the dragon out of heaven.', 'Curated', 'Daniel 10:13', 5, 'michael_2068'),
('apollyon_2', 'Apollyon', 'Abaddon', 'Angel', 'Angel', 'Named', 'New Testament', false, '''The angel of the bottomless pit'', king over the locusts of the fifth trumpet; Abaddon in Hebrew, Apollyon in Greek, both meaning destroyer. Commonly understood as a demonic power, sometimes identified with Satan.', 'Curated', 'Revelation 9:11', 1, 'apollyon_2'),
('baal_573', 'Baal', 'Baal-peor; Baalim', 'FalseGod', 'FalseGod', 'Named', 'Old Testament', true, 'Canaanite storm and fertility god, worshipped under local titles such as Baal-peor. Ahab served him at Jezebel''s urging; Elijah defeated his 450 prophets on Mount Carmel, and Jehu destroyed his worship in Israel. Gideon tore down his altar.', 'Curated', 'Numbers 22:41', 52, 'baal_573'),
('baal-zebub_579', 'Baal-zebub', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, '''Lord of flies'', god of the Philistine city of Ekron. King Ahaziah of Israel sent to inquire of him after a fall, and Elijah rebuked him for it. The New Testament form Beelzebub is used of the prince of demons.', 'Curated', '2 Kings 1:2', 4, 'baal-zebub_579'),
('molech_2104', 'Molech', 'Moloch; Molek', 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'God of the Ammonites associated with child sacrifice, which the Law forbade on pain of death. Solomon built a high place for him; Josiah defiled Topheth so that no one would make a child pass through the fire to Molech.', 'Curated', 'Leviticus 18:21', 8, 'molech_2104'),
('milcom_2084', 'Milcom', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, '''The abomination of the Ammonites'', whom Solomon followed in his old age. Josiah defiled the high places Solomon had built for him.', 'Curated', '1 Kings 11:5', 3, 'milcom_2084'),
('chemosh_931', 'Chemosh', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'National god of Moab (''the abomination of Moab''). Solomon built a high place for him east of Jerusalem, which Josiah later defiled; Jeremiah foretold that Moab would be ashamed of Chemosh.', 'Curated', 'Numbers 21:29', 8, 'chemosh_931'),
('dagon_969', 'Dagon', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'Chief god of the Philistines. Samson pulled down his temple at Gaza; when the captured ark was set in his temple at Ashdod, his image fell before it and was broken. Saul''s head was fastened in his temple.', 'Curated', 'Judges 16:23', 7, 'dagon_969'),
('ashtoreth_341', 'Ashtoreth', 'Ashtaroth (plural); Astarte', 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, '''The goddess of the Zidonians'', a Canaanite fertility goddess. Solomon followed her in his old age, and Josiah defiled the high places built for her.', 'Curated', '1 Kings 11:5', 3, 'ashtoreth_341'),
('diana_1008', 'Diana', 'Artemis', 'FalseGod', 'FalseGod', 'Named', 'New Testament', false, '''Great Diana of the Ephesians'' (Greek Artemis), whose temple at Ephesus was one of the wonders of the world. Demetrius and the silversmiths who made her shrines started a riot against Paul''s preaching.', 'Curated', 'Acts 19:24', 5, 'diana_1008'),
('adrammelech_103', 'Adrammelech, god of Sepharvaim', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'God of the Sepharvites settled in Samaria by the Assyrians, to whom they burned their children in the fire. Not to be confused with Adrammelech son of Sennacherib.', 'Curated', '2 Kings 17:31', 1, 'adrammelech_103'),
('anammelech_254', 'Anammelech', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'God of the Sepharvites, worshipped alongside Adrammelech with child sacrifice by the peoples settled in Samaria.', 'Curated', '2 Kings 17:31', 1, 'anammelech_254'),
('nisroch_9201', 'Nisroch', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'Assyrian god in whose temple at Nineveh Sennacherib was worshipping when his sons Adrammelech and Sharezer killed him.', 'Curated', '2 Kings 19:37', 2, NULL),
('rimmon_9202', 'Rimmon, god of Syria', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'Syrian god worshipped at Damascus. Naaman, healed of leprosy, asked pardon in advance for bowing in the house of Rimmon when his master leaned on his arm.', 'Curated', '2 Kings 5:18', 1, NULL),
('nebo_9203', 'Nebo, god of Babylon', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'Babylonian god of writing and wisdom (Nabu), pictured by Isaiah with Bel as an idol stooping and carried off on beasts of burden.', 'Curated', 'Isaiah 46:1', 1, NULL),
('bel_9204', 'Bel', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'Title (''lord'') of the chief god of Babylon, identified with Merodach. Isaiah and Jeremiah foretold his humiliation when Babylon fell.', 'Curated', 'Isaiah 46:1', 3, NULL),
('merodach_9205', 'Merodach', 'Marduk', 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'Patron god of Babylon (Marduk). Jeremiah announced that Merodach would be broken in pieces when Babylon was taken.', 'Curated', 'Jeremiah 50:2', 1, NULL),
('tammuz_9206', 'Tammuz', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'Mesopotamian dying-and-rising god. In a vision Ezekiel saw women at the north gate of the Temple weeping for Tammuz, one of the abominations that provoked judgement on Jerusalem.', 'Curated', 'Ezekiel 8:14', 1, NULL),
('nergal_9207', 'Nergal', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'God of the men of Cuth (Cuthah), worshipped by them after the Assyrians resettled them in Samaria.', 'Curated', '2 Kings 17:30', 1, NULL),
('ashima_9208', 'Ashima', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'God of the men of Hamath, worshipped by them after the Assyrians resettled them in Samaria.', 'Curated', '2 Kings 17:30', 1, NULL),
('succoth_benoth_9209', 'Succoth-benoth', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'Deity made by the men of Babylon who were resettled in Samaria by the Assyrians.', 'Curated', '2 Kings 17:30', 1, NULL),
('nibhaz_9210', 'Nibhaz', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'God of the Avites, worshipped by them after the Assyrians resettled them in Samaria.', 'Curated', '2 Kings 17:31', 1, NULL),
('tartak_9211', 'Tartak', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'God of the Avites, worshipped alongside Nibhaz by the peoples resettled in Samaria.', 'Curated', '2 Kings 17:31', 1, NULL),
('remphan_9212', 'Remphan', 'Chiun', 'FalseGod', 'FalseGod', 'Named', 'Old Testament', true, 'Star god whose image Israel carried in the wilderness, named Chiun by Amos and Remphan in Stephen''s quotation of Amos in Acts; usually identified with Saturn.', 'Curated', 'Amos 5:26', 2, NULL),
('baal_berith_9213', 'Baal-berith', 'El-berith; Berith', 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, '''Lord of the covenant'', worshipped at Shechem. After Gideon''s death Israel made him their god, and his temple treasury funded Abimelech''s hired men.', 'Curated', 'Judges 8:33', 3, NULL),
('queen_of_heaven_9214', 'Queen of heaven', NULL, 'FalseGod', 'FalseGod', 'Named', 'Old Testament', false, 'Goddess to whom the families of Judah baked cakes and poured drink offerings, and whose worship the refugees in Egypt defended to Jeremiah''s face; probably the Assyro-Babylonian Ishtar.', 'Curated', 'Jeremiah 7:18', 5, NULL),
('jupiter_9215', 'Jupiter', 'Zeus', 'FalseGod', 'FalseGod', 'Named', 'New Testament', false, 'Chief Greek god (Zeus). After Paul healed a lame man at Lystra, the crowd called Barnabas Jupiter, and the priest of Jupiter brought oxen to sacrifice to them.', 'Curated', 'Acts 14:12', 2, NULL),
('mercurius_9216', 'Mercurius', 'Hermes; Mercury', 'FalseGod', 'FalseGod', 'Named', 'New Testament', false, 'Greek messenger god (Hermes). The people of Lystra called Paul Mercurius ''because he was the chief speaker''.', 'Curated', 'Acts 14:12', 1, NULL),
('angel_of_the_lord_9101', 'Angel of the Lord', NULL, 'Angel', 'Angel', 'Descriptive', 'Old Testament', false, 'Messenger of the Lord in the Old Testament who often speaks in God''s own name. He found Hagar in the wilderness, stopped Abraham from sacrificing Isaac, appeared in the burning bush, blocked Balaam''s way, called Gideon, announced Samson''s birth, fed Elijah and struck the Assyrian camp. Many identify him with a pre-incarnate appearance of Christ; modelled here as one being. New Testament angels ''of the Lord'' are separate entries.', 'Curated', 'Genesis 16:7', 77, NULL),
('man_who_wrestled_jacob_9102', 'Man who wrestled with Jacob', NULL, 'Angel', 'Angel', 'Descriptive', 'Old Testament', false, 'Figure who wrestled with Jacob at Peniel until daybreak, put his hip out of joint, renamed him Israel and blessed him. Genesis calls him a man; Hosea says Jacob ''had power over the angel''. Jacob said he had seen God face to face.', 'Curated', 'Genesis 32:24', 8, NULL),
('captain_of_the_host_9118', 'Captain of the LORD''s host', NULL, 'Angel', 'Angel', 'Descriptive', 'Old Testament', false, 'Man with a drawn sword who met Joshua near Jericho and said he had come as captain of the host of the LORD. Joshua fell on his face and worshipped, and was told to loose his shoe, for the place was holy.', 'Curated', 'Joshua 5:13', 3, NULL),
('destroyer_of_egypt_9103', 'Destroyer in Egypt', NULL, 'Angel', 'Angel', 'Descriptive', 'Old Testament', true, '''The destroyer'' who passed through Egypt on the night of the first Passover and struck the firstborn, passing over houses marked with the lamb''s blood.', 'Curated', 'Exodus 12:23', 2, NULL),
('seraph_of_isaiah_9104', 'Seraph who touched Isaiah', NULL, 'Seraph', 'Angel', 'Descriptive', 'Old Testament', false, 'One of the seraphim of Isaiah''s temple vision, who flew to him with a live coal from the altar, touched his lips and declared his iniquity taken away.', 'Curated', 'Isaiah 6:6', 2, NULL),
('fourth_man_in_the_furnace_9105', 'Fourth man in the furnace', NULL, 'Angel', 'Angel', 'Descriptive', 'Old Testament', false, 'Figure seen walking in the fiery furnace with Shadrach, Meshach and Abednego, ''like the Son of God''; Nebuchadnezzar said God had sent his angel and delivered them.', 'Curated', 'Daniel 3:25', 2, NULL),
('angel_in_the_lions_den_9106', 'Angel in the lions'' den', NULL, 'Angel', 'Angel', 'Descriptive', 'Old Testament', false, 'Angel God sent to shut the lions'' mouths so that they did not hurt Daniel.', 'Curated', 'Daniel 6:22', 1, NULL),
('man_clothed_in_linen_9107', 'Man clothed in linen', NULL, 'Angel', 'Angel', 'Descriptive', 'Old Testament', false, 'Glorious figure who appeared to Daniel by the Tigris. He said the prince of the kingdom of Persia withstood him twenty-one days until Michael came to help, and revealed what would befall Daniel''s people in the latter days.', 'Curated', 'Daniel 10:5', 19, NULL),
('angel_to_joseph_9108', 'Angel who appeared to Joseph', NULL, 'Angel', 'Angel', 'Descriptive', 'New Testament', false, 'Angel of the Lord who spoke to Joseph in dreams: telling him to take Mary as his wife, to flee to Egypt from Herod, and to return to Israel after Herod''s death.', 'Curated', 'Matthew 1:20', 6, NULL),
('angel_to_the_shepherds_9109', 'Angel who appeared to the shepherds', NULL, 'Angel', 'Angel', 'Descriptive', 'New Testament', false, 'Angel of the Lord who appeared to the shepherds near Bethlehem, announced the birth of a Saviour, Christ the Lord, and was joined by a multitude of the heavenly host.', 'Curated', 'Luke 2:9', 7, NULL),
('angel_in_gethsemane_9110', 'Angel in Gethsemane', NULL, 'Angel', 'Angel', 'Descriptive', 'New Testament', false, 'Angel from heaven who appeared to Jesus in his agony on the Mount of Olives and strengthened him. The verse is absent from some early manuscripts.', 'Curated', 'Luke 22:43', 1, NULL),
('angel_at_the_tomb_9111', 'Angel at the tomb', NULL, 'Angel', 'Angel', 'Descriptive', 'New Testament', false, 'Angel of the Lord who rolled back the stone from Jesus'' tomb and sat on it, his appearance like lightning, and told the women that Jesus had risen. Mark describes a young man in white; Luke and John two figures.', 'Curated', 'Matthew 28:2', 6, NULL),
('angel_who_freed_the_apostles_9112', 'Angel who freed the apostles', NULL, 'Angel', 'Angel', 'Descriptive', 'New Testament', false, 'Angel of the Lord who opened the doors of the common prison by night, brought the apostles out and told them to speak in the Temple.', 'Curated', 'Acts 5:19', 2, NULL),
('angel_who_freed_peter_9113', 'Angel who freed Peter', NULL, 'Angel', 'Angel', 'Descriptive', 'New Testament', false, 'Angel of the Lord who woke Peter in Herod''s prison, made his chains fall off and led him past two guards and through the iron gate into the city.', 'Curated', 'Acts 12:7', 5, NULL),
('angel_who_struck_herod_9114', 'Angel who struck Herod', NULL, 'Angel', 'Angel', 'Descriptive', 'New Testament', false, 'Angel of the Lord who struck Herod Agrippa I because he accepted the people''s acclaim as a god; he was eaten of worms and died.', 'Curated', 'Acts 12:23', 1, NULL),
('angel_who_sent_philip_9115', 'Angel who sent Philip', NULL, 'Angel', 'Angel', 'Descriptive', 'New Testament', false, 'Angel of the Lord who told Philip to go south to the desert road from Jerusalem to Gaza, where he met the Ethiopian eunuch.', 'Curated', 'Acts 8:26', 1, NULL),
('angel_to_cornelius_9116', 'Angel who appeared to Cornelius', NULL, 'Angel', 'Angel', 'Descriptive', 'New Testament', false, 'Angel of God who appeared to Cornelius in a vision at the ninth hour and told him to send to Joppa for Simon Peter.', 'Curated', 'Acts 10:3', 10, NULL),
('angel_with_paul_in_the_storm_9117', 'Angel who stood by Paul in the storm', NULL, 'Angel', 'Angel', 'Descriptive', 'New Testament', false, 'Angel of God who stood by Paul during the storm at sea and assured him that he would stand before Caesar and that all who sailed with him would be saved.', 'Curated', 'Acts 27:23', 2, NULL),
('legion_9120', 'Legion', NULL, 'Demon', 'Demon', 'Named', 'New Testament', false, 'Name given by the many demons possessing the Gerasene man: ''My name is Legion: for we are many.'' They begged not to be sent away and were allowed into a herd of about two thousand pigs, which ran into the sea.', 'Curated', 'Mark 5:9', 9, NULL),
('unclean_spirit_of_capernaum_9121', 'Unclean spirit in the Capernaum synagogue', NULL, 'Demon', 'Demon', 'Descriptive', 'New Testament', false, 'Unclean spirit that cried out through a man in the synagogue at Capernaum, ''I know thee who thou art, the Holy One of God.'' Jesus rebuked it and it came out of him.', 'Curated', 'Mark 1:23', 7, NULL),
('dumb_and_deaf_spirit_9122', 'Dumb and deaf spirit', NULL, 'Demon', 'Demon', 'Descriptive', 'New Testament', false, 'Spirit that possessed a boy from childhood, threw him into fire and water to destroy him, and left him unable to speak. The disciples could not cast it out; Jesus commanded it to come out and enter him no more.', 'Curated', 'Mark 9:17', 10, NULL),
('demon_of_the_mute_man_9123', 'Demon of the mute man', NULL, 'Demon', 'Demon', 'Descriptive', 'New Testament', false, 'Demon that made a man mute. When Jesus cast it out the man spoke.', 'Curated', 'Matthew 9:32', 2, NULL),
('demon_of_the_syrophoenician_daughter_9124', 'Demon of the Syrophoenician woman''s daughter', NULL, 'Demon', 'Demon', 'Descriptive', 'New Testament', false, 'Unclean spirit that possessed the young daughter of the Syrophoenician woman. Jesus drove it out from a distance in answer to her mother''s faith.', 'Curated', 'Mark 7:25', 6, NULL),
('spirit_of_divination_9125', 'Spirit of divination', NULL, 'Demon', 'Demon', 'Descriptive', 'New Testament', false, 'Spirit (literally ''a spirit of Python'') that enabled a slave girl at Philippi to tell fortunes. Paul commanded it in the name of Jesus Christ to come out of her, and it came out that same hour.', 'Curated', 'Acts 16:16', 3, NULL),
('spirit_of_infirmity_9126', 'Spirit of infirmity', NULL, 'Demon', 'Demon', 'Descriptive', 'New Testament', false, 'Spirit that kept a woman bent double for eighteen years; Jesus said Satan had bound her, and loosed her on the Sabbath.', 'Curated', 'Luke 13:11', 6, NULL),
('evil_spirit_of_ephesus_9127', 'Evil spirit at Ephesus', NULL, 'Demon', 'Demon', 'Descriptive', 'New Testament', false, 'Evil spirit that answered the seven sons of Sceva, who tried to cast it out in the name of Jesus whom Paul preached: ''Jesus I know, and Paul I know; but who are ye?'' The possessed man overpowered them.', 'Curated', 'Acts 19:15', 4, NULL),
('evil_spirit_upon_saul_9128', 'Evil spirit upon Saul', NULL, 'Spirit', 'SpiritualBeing', 'Descriptive', 'Old Testament', false, 'Evil spirit ''from the LORD'' that troubled Saul after the Spirit of the LORD departed from him. David''s harp playing relieved him, but under its influence Saul twice hurled his spear at David.', 'Curated', '1 Samuel 16:14', 6, NULL),
('lying_spirit_9129', 'Lying spirit', NULL, 'Spirit', 'SpiritualBeing', 'Descriptive', 'Old Testament', false, 'Spirit in Micaiah''s vision of the heavenly court that offered to be a lying spirit in the mouths of Ahab''s prophets, enticing Ahab to go up to his death at Ramoth-gilead.', 'Curated', '1 Kings 22:21', 6, NULL),
('prince_of_persia_9130', 'Prince of the kingdom of Persia', NULL, 'Principality', 'Principality', 'Descriptive', 'Old Testament', false, 'Spiritual prince who withstood the angelic messenger sent to Daniel for twenty-one days until Michael came to help; usually understood as a hostile power over Persia.', 'Curated', 'Daniel 10:13', 2, NULL),
('prince_of_grecia_9131', 'Prince of Grecia', NULL, 'Principality', 'Principality', 'Descriptive', 'Old Testament', false, 'Spiritual prince whose coming the messenger to Daniel foretold after the conflict with the prince of Persia; usually understood as a hostile power over Greece.', 'Curated', 'Daniel 10:20', 1, NULL);
