('dumb_and_deaf_spirit_9122', 'muteness, deafness and seizures (Mark 9:17-18, 9:25)', 'One'),
('demon_of_the_mute_man_9123', 'muteness (Matthew 9:32)', 'One'),
('demon_of_the_syrophoenician_daughter_9124', 'grievous vexation (Matthew 15:22)', 'One'),
('spirit_of_divination_9125', 'fortune-telling (Acts 16:16)', 'One'),
