('baal-zebub_579', 'Philistine', 'oracle ("lord of flies")', 'Ekron', 'consulted about recovery from sickness (2 Kings 1:2)'),
('molech_2104', 'Ammonite', NULL, 'Topheth in the valley of Hinnom (2 Kings 23:10)', 'making children pass through the fire'),
('milcom_2084', 'Ammonite', NULL, 'high place on the mount of corruption, Jerusalem (2 Kings 23:13)', NULL),
('chemosh_931', 'Moabite', 'national god of Moab', 'Moab; high place east of Jerusalem (1 Kings 11:7)', NULL),
('dagon_969', 'Philistine', 'grain or fish (disputed)', 'Gaza; Ashdod', 'sacrifices; trophies of war hung in his temple (1 Chronicles 10:10)'),
('ashtoreth_341', 'Sidonian', 'fertility, love and war', 'Sidon; high place before Jerusalem (2 Kings 23:13)', NULL),
('diana_1008', 'Greek (Ephesian Artemis)', 'mother goddess of fertility', 'Ephesus', 'silver shrines made by silversmiths (Acts 19:24)'),
('adrammelech_103', 'Sepharvite', NULL, 'Sepharvaim; Samaria', 'burning children in fire (2 Kings 17:31)'),
('anammelech_254', 'Sepharvite', NULL, 'Sepharvaim; Samaria', 'burning children in fire (2 Kings 17:31)'),
('nisroch_9201', 'Assyrian', NULL, 'Nineveh', NULL),
('rimmon_9202', 'Syrian (Aramean)', 'storm (Hadad-Rimmon)', 'Damascus', 'bowing in the house of Rimmon (2 Kings 5:18)'),
('nebo_9203', 'Babylonian', 'writing and wisdom', 'Babylon', 'idols carried on beasts (Isaiah 46:1)'),
('bel_9204', 'Babylonian', 'chief god ("lord")', 'Babylon', NULL),
('merodach_9205', 'Babylonian', 'patron god of Babylon', 'Babylon', NULL),
('tammuz_9206', 'Mesopotamian', 'vegetation; dying and rising', 'north gate of the Temple, Jerusalem (Ezekiel 8:14)', 'ritual weeping by women'),
('nergal_9207', 'Cuthite', 'plague and the underworld', 'Cuthah; Samaria', NULL),
('ashima_9208', 'Hamathite', NULL, 'Hamath; Samaria', NULL),
('succoth_benoth_9209', 'Babylonian', NULL, 'Samaria', NULL),
('nibhaz_9210', 'Avite', NULL, 'Samaria', NULL),
('tartak_9211', 'Avite', NULL, 'Samaria', NULL),
('remphan_9212', 'astral', 'star god, usually identified with Saturn', 'carried in the wilderness', 'images carried in procession (Amos 5:26; Acts 7:43)'),
